update public.content_variants set body = $json${"type":"multiple_choice","answer":"Volatility of banking stocks and bond yields","options":["Only gold prices","Volatility of banking stocks and bond yields","Number of influencer followers","Color of stock charts"],"question":"A change in the BI Rate policy can affect ...","difficulty":"intermediate","parameters":{},"explanation":"The benchmark interest rate affects the financial sector and fixed income instruments."}$json$::jsonb where id = '05a4e48c-af4d-4a85-8762-81884e5464e6';
update public.content_variants set body = $json${"type":"word_bank","answer":["price fluctuations","investor responsibility"],"options":["price fluctuations","investor responsibility"],"question":"Complete: \"Volatility is _____, while emotional control is _____.\"","difficulty":"intermediate","parameters":{},"explanation":"We cannot control the market, but we can control our own reactions."}$json$::jsonb where id = '0642a816-0d92-4eb9-a23b-f5db0adbe041';
update public.content_variants set body = $json${"text":"Two students with the same allowance can have different risk profiles. The one with a 6-month emergency fund is more prepared to face stock fluctuations than Fikri, who is just starting to save.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953"]}$json$::jsonb where id = '08b0902a-4922-4bf5-b492-c075a545e505';
update public.content_variants set body = $json${"text":"Siti, a student, has a 6-month emergency fund and a 10-year investment horizon. She chooses a mix of blue-chip stocks and mutual funds. Her friend Fikri, who doesn't have an emergency fund yet, should focus on saving first before investing in stocks.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '0c01a9c0-08ff-4026-9909-d56097bcb516';
update public.content_variants set body = $json${"type":"fill_blank","answer":"plan","question":"A way to control emotions during high volatility is to create an investment _____ and set limits on checking prices.","difficulty":"intermediate","parameters":{},"explanation":"A plan made when calm helps avoid impulsive decisions during market turbulence."}$json$::jsonb where id = '0c041de3-4d16-4b4a-ad81-99c49ad1e8c6';
update public.content_variants set body = $json${"type":"fill_blank","answer":"aggressive","question":"Young investors with a long horizon can usually consider a slightly more _____ profile.","difficulty":"intermediate","parameters":{},"explanation":"A long time horizon provides an opportunity to withstand market fluctuations."}$json$::jsonb where id = '0ca2c32e-5651-46ac-9370-e79800087076';
update public.content_variants set body = $json${"text":"Two people with the same income can have different risk tolerances. Those with large family responsibilities might be more conservative, while those who are single and have an emergency fund can be more aggressive.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953"]}$json$::jsonb where id = '150878a9-a98f-4cf3-9d0b-f92a871ca8af';
update public.content_variants set body = $json${"text":"Risk tolerance is not about being brave or not, but about how much fluctuation you can accept without disturbing your sleep and finances. Overconfidence can lead to overtrading. Know yourself before choosing instruments.","ai_assist_context":"Help users assess their risk tolerance by considering income, responsibilities, and financial goals."}$json$::jsonb where id = '161d4ffc-3f94-4cb3-a301-59ecb28d5442';
update public.content_variants set body = $json${"type":"ordering","answer":["Evaluate income and responsibilities","Determine goals and time horizon","Recognize emotional reactions to losses","Choose suitable instruments"],"options":["Evaluate income and responsibilities","Determine goals and time horizon","Recognize emotional reactions to losses","Choose suitable instruments"],"question":"Order the steps to determine a risk profile.","difficulty":"intermediate","parameters":{},"explanation":"Understand financial conditions, goals, emotional reactions, then choose suitable instruments."}$json$::jsonb where id = '1693b54c-64e0-4660-982d-7ee60fc7dc19';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Overconfidence usually makes investors more cautious and trade less frequently.","difficulty":"intermediate","parameters":{},"explanation":"Overconfidence tends to lead to overtrading and underestimating risks."}$json$::jsonb where id = '1aafccd0-b529-4189-aa1d-1fd7631d5f7b';
update public.content_variants set body = $json${"text":"Rina keeps an investment journal: every time she wants to sell, she must write down her reason. This journal makes her realize that many of her selling desires come from emotions, not fundamental changes.","source_ids":["5fa2799e-2b92-46e8-b68a-c9d64847410c"]}$json$::jsonb where id = '1e085705-92ef-47ab-9b76-4ce0ff7d5221';
update public.content_variants set body = $json${"text":"The campus investment class learned that volatility is not the same as permanent loss. A loss only occurs if we sell when the price is below the purchase price due to panic.","source_ids":["c7c57d03-733f-4fe8-bd15-ce3a1cd4a760"]}$json$::jsonb where id = '23ba2ff6-8220-425c-a253-fd9ede922a75';
update public.content_variants set body = $json${"text":"Maya is investing for the first time and immediately believes she can analyze financial statements. After losing on her first stock, she realizes that gradual learning is more important than overconfidence.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '274f115a-974e-4a98-b733-74250cc2f312';
update public.content_variants set body = $json${"type":"ordering","answer":["Create a reason for buying before the transaction","Set an acceptable loss limit","Don't check prices every minute","Review the portfolio according to schedule"],"options":["Set an acceptable loss limit","Create a reason for buying before the transaction","Don't check prices every minute","Review the portfolio according to schedule"],"question":"Order the steps so that loss aversion doesn't dominate decisions.","difficulty":"intermediate","parameters":{},"explanation":"Planning before transactions, setting loss limits, controlling price checks, and scheduled reviews help manage emotions."}$json$::jsonb where id = '3039344a-1a4c-4e76-afc9-79fc61ae885a';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"The rise and fall of asset prices","options":["Amount of dividends","The rise and fall of asset prices","Investment taxes","Number of shares"],"question":"Volatility measures ...","difficulty":"intermediate","parameters":{},"explanation":"Volatility shows how much asset prices fluctuate over a period."}$json$::jsonb where id = '36e8f23e-8868-4314-a9bc-9aa7ee974f7d';
update public.content_variants set body = $json${"text":"Rina has a money market mutual fund and UNVR stocks. When her portfolio drops by Rp 200,000, she remembers that loss more than the Rp 200,000 gain from last week. This asymmetric feeling is called loss aversion.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '37c091b2-86cb-414c-a86a-6aef3972aeb1';
update public.content_variants set body = $json${"text":"Bank Indonesia publishes the BI Rate, which affects deposit interest rates and bond yields. Investors who understand this context do not panic and change strategies just because of one news item.","source_ids":["097b62c4-9aae-4933-a870-ac74a526b8f1"]}$json$::jsonb where id = '42c3df35-1ee4-4042-8521-66118541ba76';
update public.content_variants set body = $json${"type":"ordering","answer":["Set limits on portfolio checks","Remember long-term goals","Reevaluate the reasons for buying","Avoid major decisions when emotions are high"],"options":["Remember long-term goals","Set limits on portfolio checks","Reevaluate the reasons for buying","Avoid major decisions when emotions are high"],"question":"Order the steps to stay calm during a volatile market.","difficulty":"intermediate","parameters":{},"explanation":"Limit price checks, remember goals, evaluate reasons, and avoid decisions when emotions peak."}$json$::jsonb where id = '46e19447-7376-4a97-a11d-563924f80771';
update public.content_variants set body = $json${"text":"Lina, a new employee with a salary of Rp 7,000,000, immediately bought GOTO stocks and some speculative stocks because she believed she could \"play the stock market.\" Within a month, she lost 20% of her capital due to overtrading and transaction costs.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '4746696d-7635-45b6-ab84-419d9c39a352';
update public.content_variants set body = $json${"type":"word_bank","answer":["aggressive","conservative"],"options":["aggressive","conservative"],"question":"Complete: \"Young investors with a long horizon can usually be more _____, while retirees tend to be more _____.\"","difficulty":"intermediate","parameters":{},"explanation":"A long horizon allows young investors to take on more risk; retirees usually need stability."}$json$::jsonb where id = '4fe83503-a476-4a57-80d9-e3de81fa5dda';
update public.content_variants set body = $json${"type":"ordering","answer":["Create an investment plan","Set price check limits","Focus on long-term goals","Avoid decisions during high emotions"],"options":["Create an investment plan","Set price check limits","Focus on long-term goals","Avoid decisions during high emotions"],"question":"Order the ways to handle volatility.","difficulty":"intermediate","parameters":{},"explanation":"Planning, limits, goal focus, and emotional control help handle volatility."}$json$::jsonb where id = '54177567-1072-4f01-98ab-64bb8a08128b';
update public.content_variants set body = $json${"text":"Salsa bought BBRI and TLKM stocks as part of her long-term portfolio. Every time there's negative news, she panics and wants to sell. Her friend reminds her: it's okay to fear losses, but don't let emotions change the plan you made when calm."}$json$::jsonb where id = '57489e26-52d8-4cbe-843e-207d55bc6d79';
update public.content_variants set body = $json${"text":"Volatility is a normal part of stock investing. The important thing is not to eliminate fluctuations, but to control emotional reactions. Make a plan, set price check limits, and focus on long-term goals."}$json$::jsonb where id = '64666f95-c038-40bc-ad30-c99b6cb8e76a';
update public.content_variants set body = $json${"text":"GOTO stock can rise 8% in one day and fall 7% the next day. Daily fluctuations like this are normal for high-growth stocks. Long-term investors don't need to panic every time the price moves."}$json$::jsonb where id = '6587bda6-a9bb-4022-91e0-d921275cd99d';
update public.content_variants set body = $json${"text":"A trader on social media boasts about making a profit of Rp 50 million in a week. Riko wants to imitate but doesn't realize their capital and experience are different. Overconfidence can arise when we only see others' good results."}$json$::jsonb where id = '65c169bb-3e7c-4e80-ba4b-cd0a61478ec5';
update public.content_variants set body = $json${"text":"Ahmad has a portfolio of blue-chip stocks and mutual funds. When the market drops 5% in a month, his portfolio falls 3%. He doesn't panic because he understands volatility and has a plan."}$json$::jsonb where id = '68e6e867-58e5-47f1-98af-62a1ad5d4f32';
update public.content_variants set body = $json${"type":"word_bank","answer":["profile","lifestyle"],"options":["profile","lifestyle"],"question":"Complete: \"Choose instruments according to your own risk _____, not following someone else's _____.\"","difficulty":"intermediate","parameters":{},"explanation":"Investment decisions should be tailored to personal risk profiles, not influencer lifestyles."}$json$::jsonb where id = '6bb4ef6d-1319-4973-9709-9fb6b8c86881';
update public.content_variants set body = $json${"text":"Fikri made a rule: only buy new stocks after reading financial reports for at least 15 minutes. This rule helps him resist FOMO when seeing friends' profit posts on social media."}$json$::jsonb where id = '7058f2c8-eba4-4873-83d8-827bc4592d46';
update public.content_variants set body = $json${"text":"Nadia bought UNVR stock and set a rule to check the app only once a week. This rule reduces her urge to react every time the price changes slightly."}$json$::jsonb where id = '719890f8-3e54-47cf-8d98-b765438b910a';
update public.content_variants set body = $json${"text":"Rina's friend posted a screenshot of a 30% profit from a new crypto stock. Rina felt envious and immediately bought without research. Two weeks later, the crypto price dropped 40%. This experience taught her that FOMO can be more costly than a semester's tuition."}$json$::jsonb where id = '760a07ea-ebea-4362-ac45-98a8a0789676';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Age, income, and financial goals","options":["Number of Instagram followers","Age, income, and financial goals","Color of stock logo","Number of friends trading"],"question":"Factors that influence risk tolerance include ...","difficulty":"intermediate","parameters":{},"explanation":"Risk tolerance depends on personal conditions, not popularity or trends."}$json$::jsonb where id = '764d55e3-aadc-408f-a899-2bff75554281';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Deposits and government bonds","options":["Speculative stocks","Deposits and government bonds","Highly volatile crypto","Penny stocks"],"question":"Retirees relying on savings should tend to choose ... instruments","difficulty":"intermediate","parameters":{},"explanation":"Retirees typically have a more conservative risk profile because they need stability."}$json$::jsonb where id = '76553c1e-4365-464b-b82d-b047ed73c863';
update public.content_variants set body = $json${"type":"fill_blank","answer":"emotional","question":"The biggest risk for long-term investors is often an overly _____ reaction.","difficulty":"intermediate","parameters":{},"explanation":"Overly emotional reactions can lead to selling below fair value."}$json$::jsonb where id = '80670f4a-2d37-4e5f-901b-e31fdd8b909e';
update public.content_variants set body = $json${"text":"A FOMO investor buys GOTO when it rises 15% in a week. It turns out the price then corrects. They learn that short-lived euphoria can lead to painful volatility.","source_ids":["c7c57d03-733f-4fe8-bd15-ce3a1cd4a760"]}$json$::jsonb where id = '89da55fd-b46e-4139-9ed6-e56232e11053';
update public.content_variants set body = $json${"text":"Budi owns BBCA shares priced at Rp 9,000 each. When the price drops to Rp 8,600, he feels a \"big loss\" even though it's only about a 4% drop. Loss aversion makes him want to sell immediately, even though the bank's fundamentals remain strong.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953"]}$json$::jsonb where id = '8b576b44-61ca-41f5-b392-eb8ce1fc9c7d';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Trading too often and underestimating risk","options":["Trading too often and underestimating risk","Saving with discipline","Always checking financial reports","Diversifying the portfolio carefully"],"question":"Overconfident investors tend to ...","difficulty":"intermediate","parameters":{},"explanation":"Overconfidence often leads investors to overtrade and ignore risks."}$json$::jsonb where id = '9407f0eb-2853-4d51-91c8-8e8d3e1af191';
update public.content_variants set body = $json${"text":"Mr. Tono saves Rp 50 million in a BCA deposit with stable returns. His friend says it's a \"loss\" because stocks can yield higher profits, but Mr. Tono feels comfortable because he doesn't worry about daily price drops. Everyone has different loss aversion limits.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953"]}$json$::jsonb where id = '94e6cad2-938a-4519-92d6-44e31b577479';
update public.content_variants set body = $json${"type":"ordering","answer":["Calculate emergency funds and liabilities","Determine investment time horizon","Test emotional reaction when portfolio drops","Choose suitable instruments"],"options":["Calculate emergency funds and liabilities","Determine investment time horizon","Test emotional reaction when portfolio drops","Choose suitable instruments"],"question":"Order the steps to assess risk tolerance.","difficulty":"intermediate","parameters":{},"explanation":"Understand financial conditions, time horizon, emotional reactions, then choose suitable instruments."}$json$::jsonb where id = '993dc340-a8db-434e-be08-eafcc96848d0';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"The pain of losing Rp 100,000 is usually as great as the joy of gaining Rp 100,000.","difficulty":"intermediate","parameters":{},"explanation":"Loss aversion shows that the pain of loss is usually stronger than the joy of an equivalent gain."}$json$::jsonb where id = '9b4643a0-ed9b-48ef-bb1e-32cad5f9d194';
update public.content_variants set body = $json${"type":"word_bank","answer":["market","emotions"],"options":["market","emotions"],"question":"Complete: \"We cannot control the _____, but we can control our _____.\"","difficulty":"intermediate","parameters":{},"explanation":"Market volatility is beyond control, but our emotional reactions can be managed."}$json$::jsonb where id = '9c8fcf35-23ef-407a-92e4-eafb89b2b74a';
update public.content_variants set body = $json${"text":"A Telegram group is buzzing about a new crypto token that is said to \"definitely go up.\" Andi joined in and bought Rp 1,500,000 because he was afraid of missing out. After the hype died down, the price dropped by 60%. Andi learned that FOMO often comes without clear data.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953"]}$json$::jsonb where id = '9ee94ba5-d305-45e4-b527-7864f90cd3aa';
update public.content_variants set body = $json${"text":"Loss aversion and FOMO are two emotional forces that often disrupt investment decisions. The best way to overcome them is to set rules before buying: investment goals, acceptable loss limits, and a review schedule. Don't let social media dictate your portfolio.","ai_assist_context":"Help users recognize loss aversion and FOMO, then create personal investment rules before emotions arise."}$json$::jsonb where id = '9fc5e28a-1a59-49dc-b47e-d4438b2d460a';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Everyone's risk tolerance is definitely the same if their income is the same.","difficulty":"intermediate","parameters":{},"explanation":"Risk tolerance is also influenced by dependents, emergency funds, goals, and emotional reactions."}$json$::jsonb where id = 'a0aeada8-0612-40d0-aa5a-22ceb28782b4';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Because it can lead to buying without enough research","options":["Because prices always go down","Because it can lead to buying without enough research","Because viral stocks have no risk","Because transaction costs are always zero"],"question":"Why is FOMO dangerous when buying viral stocks?","difficulty":"intermediate","parameters":{},"explanation":"FOMO makes investors follow trends without independent research, which risks causing losses."}$json$::jsonb where id = 'a6e43f6e-6fcd-438b-a680-5561f7841fbd';
update public.content_variants set body = $json${"type":"fill_blank","answer":"profile","question":"Choose investment instruments according to your own risk _____, not following influencers.","difficulty":"intermediate","parameters":{},"explanation":"Your personal risk profile determines the instruments that best suit your condition."}$json$::jsonb where id = 'a8724e4a-ea98-44a3-9b2e-d4a3b9a3d3fe';
update public.content_variants set body = $json${"text":"TLKM stock in one quarter can rise from Rp 3,800 to Rp 4,200 and then fall to Rp 3,900. Long-term investors see this fluctuation as normal, not a signal to panic.","source_ids":["5fa2799e-2b92-46e8-b68a-c9d64847410c"]}$json$::jsonb where id = 'c8b09c3c-a400-4499-a3ba-e2b6b688f89f';
update public.content_variants set body = $json${"text":"Overconfident investors often ignore risks and buy stocks based only on rumors. Realistic investors check financial reports and long-term goals before buying.","source_ids":["c7c57d03-733f-4fe8-bd15-ce3a1cd4a760"]}$json$::jsonb where id = 'ce5b30e1-2038-44d9-8629-a655f2eb7276';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Daily volatility always means the investment is bad.","difficulty":"intermediate","parameters":{},"explanation":"Daily volatility is normal in the stock market; what matters is the investor's long-term reaction."}$json$::jsonb where id = 'd0f4b73c-6bd1-4d82-8b91-017b2bc3b4bf';
update public.content_variants set body = $json${"type":"ordering","answer":["Set investment goals","Research assets before buying","Create rules for when to sell","Avoid excessive price checking"],"options":["Set investment goals","Research assets before buying","Create rules for when to sell","Avoid excessive price checking"],"question":"Order the steps to deal with FOMO.","difficulty":"intermediate","parameters":{},"explanation":"Start with goals, research, selling rules, then control emotions to avoid overreacting."}$json$::jsonb where id = 'd3ca956a-7828-4901-95c0-7aae6e332d68';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"FOMO always results in good investment decisions because many people do it.","difficulty":"intermediate","parameters":{},"explanation":"FOMO often leads to impulsive buying without adequate research."}$json$::jsonb where id = 'e06d0291-cfbf-424d-9045-8acc05745324';
